  const connections = Array.from({ length: count }, () => ({ close: (event) => closed.push(event) }))

  return {
    closed,
    instance: { documents: new Map([[ROOM, { getConnections: () => connections }]]) },
30→  }
}

function backendAnswering(answer) {
  const stores = []

  return {
    stores,
    webhook: {
      storeDocument: async (args) => {
40→        stores.push(args)
